            "prompt": "When the صِلَةٌ of a مَفْعُوْلٌ لَهُ غَيْرُ صَرِيْحٍ is in the subjunctive mood, which حَرْفٌ مَوْصُوْلٌ is used, and what usually happens to it؟",
